import {weeklyConditions,chartSVG} from './condition-chart.js';
import {createRouteMap} from './route-map.js';
import GLPK from './glpk-browser.js';
import {defaults,weekends,buildModel,optimize,weatherFor,nextDay,holiday,passCapacity,seasonCapacity} from './model.js';
const $=id=>document.getElementById(id),money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v),dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}),clock=h=>{if(h==null)return '—';const m=Math.round(h*60),hh=Math.floor(m/60);return `${hh%12||12}:${String(m%60).padStart(2,'0')} ${hh>=12?'p.m.':'a.m.'}`;};
let data,routing,glpk,result,model,routeMap,busy=false,dirty=false;
let saved={};try{saved=JSON.parse(localStorage.getItem('ski-season-v1')||'{}')}catch{}
let s={...defaults,...saved.settings,overrides:saved.settings?.overrides||{}},active=saved.active||{};
function persist(){try{localStorage.setItem('ski-season-v1',JSON.stringify({settings:s,active,mountains:data.mountains,hotels:data.hotels}))}catch{}}
function markDirty(){dirty=true;$('explain-summary').innerHTML='<p class="note">Inputs changed. Optimize again to refresh these comparisons.</p>';$('alternatives').innerHTML='';$('feasibility').innerHTML='';$('allocation').innerHTML='';if(routeMap)routeMap.invalidate();$('status').textContent='Inputs changed. Optimize again to update the plan.';persist();}
function syncSettings(){for(const k of Object.keys(defaults)){const el=$(k);if(el.type==='time')el.value=`${String(Math.floor(s[k])).padStart(2,'0')}:${String(Math.round(s[k]%1*60)).padStart(2,'0')}`;else el.value=s[k];el.addEventListener('change',()=>{if(!el.checkValidity()||el.value===''){el.reportValidity();syncValue(el,k);return;}s[k]=(el.type==='date'||el.type==='select-one')?el.value:el.type==='time'?Number(el.value.split(':')[0])+Number(el.value.split(':')[1])/60:Number(el.value);if(s.start>s.end){$('status').textContent='Season end must be after the start date.';return;}renderWeekends();renderData();markDirty();});}}
function syncValue(el,k){el.value=s[k];}
function renderWeekends(){const dates=weekends(s);$('magicWeekend').innerHTML='<option value="auto">Let the model choose</option>'+dates.map(d=>`<option value="${d}">${dateLabel(d)}–${dateLabel(nextDay(d))}${active[d]===false?' (inactive)':''}</option>`).join('');if(s.magicWeekend!=='auto'&&!dates.includes(s.magicWeekend))$('magicWeekend').innerHTML+=`<option value="${s.magicWeekend}">${s.magicWeekend} (outside season)</option>`;$('magicWeekend').value=s.magicWeekend;$('weekends').innerHTML=dates.map(d=>`<label class="weekend ${active[d]===false?'disabled':''}"><input type="checkbox" data-week="${d}" ${active[d]!==false?'checked':''}><span>${dateLabel(d)}–${dateLabel(nextDay(d))}</span><span>${holiday(d)?'Holiday':'Weekend'}</span></label>`).join('');$('weekends').querySelectorAll('input').forEach(el=>el.onchange=()=>{active[el.dataset.week]=el.checked;renderWeekends();markDirty();});for(const id of ['explain-week','weather-week']){const old=$(id).value;$(id).innerHTML=dates.map(d=>`<option value="${d}">${dateLabel(d)}</option>`).join('');if(dates.includes(old))$(id).value=old;}$('override-week').innerHTML=dates.map(d=>`<option value="${d}">${dateLabel(d)}</option>`).join('');}
function renderData(){
 $('mountains').innerHTML=data.mountains.map(m=>`<tr><td><input aria-label="Use ${m.name}" type="checkbox" data-m="${m.id}" data-key="enabled" ${m.enabled?'checked':''}></td><td><b>${m.name}</b><br><span class="pass ${m.passType==='Indy'?'indy':''}">${m.passType}</span></td><td>${(routing.durations[0][m.id]/3600*(1+s.traffic/100)).toFixed(2)} h<br>${Math.round(routing.distances[0][m.id]/1609.344)} mi</td><td><input aria-label="${m.name} preference" type="number" min="0" max="1" step="0.05" data-m="${m.id}" data-key="preference" value="${m.preference}"></td><td><input aria-label="${m.name} crowd factor" type="number" min="0" max="1" step="0.05" data-m="${m.id}" data-key="crowd" value="${m.crowd}"></td><td><input aria-label="${m.name} remaining days" type="number" min="0" max="2" step="1" data-m="${m.id}" data-key="limit" value="${seasonCapacity(m)}"></td><td><input aria-label="${m.name} parking cost" type="number" min="0" data-m="${m.id}" data-key="parking" value="${m.parking}"></td><td><input aria-label="${m.name} opens" type="date" data-m="${m.id}" data-key="open" value="${m.open}"></td><td><input aria-label="${m.name} closes" type="date" data-m="${m.id}" data-key="close" value="${m.close}"></td></tr>`).join('');
 $('mountains').querySelectorAll('input').forEach(el=>el.onchange=()=>{if(!el.checkValidity()||el.value===''){el.reportValidity();renderData();return;}let m=data.mountains.find(m=>m.id===+el.dataset.m);m[el.dataset.key]=el.type==='checkbox'?el.checked:el.type==='date'?el.value:Number(el.value);markDirty();});
 $('hotels').innerHTML=data.hotels.map(h=>`<label>${h.name}<input aria-label="${h.name} nightly room estimate" data-h="${h.id}" type="number" min="0" value="${h.nightly}"><small>$/night · estimate, before tax</small></label>`).join('');$('hotels').querySelectorAll('input').forEach(el=>el.onchange=()=>{if(!el.checkValidity()||el.value===''){el.reportValidity();renderData();return;}data.hotels.find(h=>h.id===+el.dataset.h).nightly=Number(el.value);markDirty();});$('override-town').innerHTML=data.hotels.map(h=>`<option value="${h.id}">${h.name}</option>`).join('');renderOverrides();renderWeather();renderConditionChart();
}
function renderConditionChart(){const rows=weeklyConditions(data,s);$('condition-chart').innerHTML=chartSVG(rows,s);const dec=rows.find(r=>r.date==='2026-12-08'),march=rows.find(r=>r.date==='2027-03-23');$('condition-summary').textContent=`December week 2 (Dec 8–14): median ${dec.median.toFixed(0)}/100. Late March (Mar 23–29): median ${march.median.toFixed(0)}/100. Equal weight to all 19 mountains; favorites shown separately.`;}
$('download-chart').onclick=()=>download('historical-ski-conditions.svg',chartSVG(weeklyConditions(data,s),s),'image/svg+xml');
function renderOverrides(){$('overrides').innerHTML=Object.entries(s.overrides).map(([key,v])=>{const [d,id]=key.split('_');return `<div class="override-item"><span>${dateLabel(d)} · ${data.hotels.find(h=>h.id===+id)?.name}: ${money(v)}</span><button data-remove="${key}" class="text-button">Remove</button></div>`}).join('');$('overrides').querySelectorAll('button').forEach(el=>el.onclick=()=>{delete s.overrides[el.dataset.remove];renderOverrides();markDirty();});}
function render(){
 const trips=result.selected,total=k=>trips.reduce((v,t)=>v+(t[k]||0),0);
 $('days').textContent=total('days');$('hours').textContent=`${(total('satHours')+total('sunHours')).toFixed(1)} planned ski hours`;$('cost').textContent=money(total('cost'));$('nights').textContent=trips.filter(t=>t.hotel).length*2;$('drive').textContent=total('drive').toFixed(1)+' driving hours';
 $('status').textContent=`${result.status} · ${result.variables.toLocaleString()} binary itinerary choices · quality score ${result.quality.toFixed(1)} · lower cost breaks quality ties`;
 $('breakdown').innerHTML=['lodging','fuel','parking','food','other'].map(k=>`<span>${k[0].toUpperCase()+k.slice(1)} <b>${money(total(k))}</b></span>`).join('');
 const selected=new Map(trips.map(t=>[t.w,t]));
 $('trips').innerHTML=weekends(s).map(w=>{if(active[w]===false)return `<div class="trip"><div class="trip-header"><b>${dateLabel(w)}–${dateLabel(nextDay(w))}</b><small>Inactive</small></div></div>`;const t=selected.get(w);if(!t)return '';if(!t.days)return `<div class="trip"><div class="trip-header"><b>${dateLabel(w)}–${dateLabel(nextDay(w))}</b><small>Stay home · season limits or trip feasibility</small></div></div>`;
 const a=data.mountains.find(m=>m.id===t.sat),b=data.mountains.find(m=>m.id===t.sun),h=data.hotels.find(h=>h.id===t.hotel);
 const day=(m,date,hours,label)=>{const wx=m?weatherFor(data,m,date,s):null;return `<div><span class="day-tag">${label}</span><div class="mountain-name">${m?.name||'Off day'}</div>${m?`<span class="pass ${m.passType==='Indy'?'indy':''}">${m.passType}</span><p>${hours.toFixed(1)} ski hours · condition index ${(wx.score*100).toFixed(0)}/100<br>${wx.depth==null?'Depth unknown':'Avg base '+wx.depth+' in'} · ${wx.terrain?wx.terrain.percent+'% terrain ('+wx.terrain.reports+' reports)':'Terrain unknown'}<br>${wx.scoreMode}</p>`:''}</div>`;};
 return `<div class="trip"><div class="trip-header"><div><b>${dateLabel(w)}–${dateLabel(nextDay(w))}</b><br><small>${t.mode}${a&&b&&a.id!==b.id?' · two mountains':''}${a?.name==='Magic'&&b?.name==='Magic'?' · Required Magic weekend':''}</small></div><b>${money(t.cost)}</b></div><div class="trip-body">${day(a,w,t.satHours,'SATURDAY')}${day(b,nextDay(w),t.sunHours,'SUNDAY')}</div><div class="trip-footer"><span>${h?'2 nights · '+h.name:'Sleep at home'}</span><span>${Math.round(t.distance)} miles · ${t.drive.toFixed(1)} h driving</span><span>${b?'Sunday leave by '+clock(Math.min(16,t.sundayLeave)):'No Sunday skiing'}</span></div><details><summary>Route & cost details</summary><p>${h?`Friday: Simsbury, CT → ${h.name}, arrive ${clock(t.fridayArrival)}.<br>Saturday: ${h.name} → ${a.name} → ${h.name}.<br>Sunday: ${h.name} → ${b.name} → Simsbury, CT.`:`${a?'Saturday: Simsbury, CT → '+a.name+' → Simsbury, CT.<br>':''}${b?'Sunday: Simsbury, CT → '+b.name+' → Simsbury, CT.':''}`}<br>Lodging ${money(t.lodging)} · fuel ${money(t.fuel)} · parking ${money(t.parking)} · food ${money(t.food)} · extras ${money(t.other)}.<br>Reservation availability and operating dates require confirmation before booking.</p></details></div>`;}).join('')||'<p class="empty">No weekends in this date range.</p>';
 const usage=data.mountains.map(m=>{const used=trips.reduce((v,t)=>v+Number(t.sat===m.id)+Number(t.sun===m.id),0);return `<span>${m.name} <b>${used}/${seasonCapacity(m)}</b></span>`});$('usage').innerHTML='<h3>Season days allocated · max 2 per mountain</h3><div class="usage">'+usage.join('')+'</div>';renderExplanation();if(routeMap){routeMap.update(result.selected,s,active);if(!$('routes').classList.contains('hidden'))routeMap.show();}
}
function renderWeather(){const w=$('weather-week').value;if(!w)return;$('weather-inputs').innerHTML=data.mountains.map(m=>{const wx=weatherFor(data,m,w,s);if(!wx)return `<tr><td>${m.name}</td><td colspan="6">No weather bin for this date.</td></tr>`;return `<tr><td>${m.name}</td><td>${wx.score.toFixed(4)}</td><td>${wx.snow.toFixed(2)}</td><td>${wx.rain.toFixed(2)}</td><td>${wx.temp.toFixed(2)}</td><td>${(wx.bad*100).toFixed(1)}%</td><td>${wx.n}</td></tr>`;}).join('');renderSnowEvidence(w);}
function renderSnowEvidence(w){const month=w.slice(5,7);$('snow-evidence').innerHTML=data.mountains.map(m=>{const wx=weatherFor(data,m,w,s),depth=data.snowHistory?.[m.id],terrain=data.terrainHistory?.[m.id],t=terrain?.terrain?.[month];return `<tr><td>${m.name}</td><td>${depth?.baseDepthIn?.[month]!=null?depth.baseDepthIn[month]+' in':'Unknown'}</td><td>${t?t.percent+'%':'Unknown'}</td><td>${t?.reports??'—'}</td><td>${s.conditionMode==='weather'?'Original weather only':wx?.scoreMode||'No condition bin'}</td><td>${depth?`<a href="${depth.source}" target="_blank" rel="noopener">Depth</a>`:''} ${terrain?`<a href="${terrain.source}" target="_blank" rel="noopener">Terrain / dates</a>`:''}</td></tr>`;}).join('');$('season-evidence').innerHTML=data.mountains.flatMap(m=>(data.terrainHistory?.[m.id]?.seasons||[]).slice(0,3).map(y=>`<tr><td>${m.name}</td><td>${y.season}</td><td>${y.opening||'Unknown'}</td><td>${y.closing||'Unknown'}</td><td><a href="${data.terrainHistory[m.id].source}" target="_blank" rel="noopener">History</a></td></tr>`)).join('');}
function renderExplanation(){
 if(!model||!result||dirty)return;const w=$('explain-week').value,chosen=result.selected.find(t=>t.w===w),opts=model.options.filter(o=>o.w===w&&o.days);
 const mname=id=>data.mountains.find(m=>m.id===id)?.name||'Off',hname=id=>data.hotels.find(h=>h.id===id)?.name||'Home';
 $('explain-summary').innerHTML=chosen?`<div class="formula"><b>Selected: ${mname(chosen.sat)} / ${mname(chosen.sun)}</b><br>${hname(chosen.hotel)} · score ${(chosen.q/1000).toFixed(3)} · ${money(chosen.cost)}<br>Input preferences and travel times influence this answer. They are assumptions, not a learned ranking of mountains.</div>`:'<p class="note">This weekend is inactive, or has not been solved with the current dates.</p>';
 const pairs=new Map();for(const o of opts){let key=o.sat+'_'+o.sun,prev=pairs.get(key);if(!prev||o.q>prev.q||(o.q===prev.q&&o.cost<prev.cost))pairs.set(key,o);}
 const ranked=[...pairs.values()].sort((a,b)=>b.q-a.q||a.cost-b.cost).slice(0,12);if(chosen?.days&&!ranked.some(o=>o.name===chosen.name))ranked.push(chosen);
 $('alternatives').innerHTML=ranked.map(o=>{const c=o.components,selected=o.name===chosen?.name;return `<tr class="${selected?'chosen-row':''}"><td><b>${mname(o.sat)} / ${mname(o.sun)}</b><br>${hname(o.hotel)}${selected?' · SELECTED':''}</td><td>${(o.satHours+o.sunHours).toFixed(2)}</td>${['weather','preference','crowds','risk','fatigue'].map(k=>`<td>${c[k].toFixed(3)}</td>`).join('')}<td><b>${(o.q/1000).toFixed(3)}</b></td><td>${money(o.cost)}</td></tr>`;}).join('')||'<tr><td colspan="9">No active itinerary choices.</td></tr>';
 const travel=(a,b)=>routing.durations[a][b]/3600*(1+s.traffic/100);
 $('feasibility').innerHTML=data.mountains.filter(m=>m.enabled).map(m=>{const best=opts.filter(o=>o.sat===m.id&&o.sun===m.id).sort((a,b)=>b.q-a.q||a.cost-b.cost)[0];let why=best?hname(best.hotel):'';if(m.limit<2)why='Fewer than 2 pass days left';else if(w<m.open||nextDay(w)>m.close)why='Outside assumed operating dates';else if(!best&&[w,nextDay(w)].some(d=>(weatherFor(data,m,d,s)?.score??0)*100+1e-9<s.minCondition))why='Below minimum condition score';else if(!best){const near=data.hotels.filter(h=>travel(h.id,m.id)<=s.commute/60&&travel(m.id,h.id)<=s.commute/60);why=!near.length?'No lodging base within commute limit':!near.some(h=>s.friday+travel(0,h.id)<=s.arrival)?'Hotel arrival exceeds Friday deadline':s.returnTime-travel(m.id,0)-.5-9<2?'Less than 2 Sunday ski hours':'Inactive weekend or no feasible itinerary';}return `<tr><td>${m.name}</td><td>${travel(m.id,0).toFixed(2)} h</td><td>${best?best.sunHours.toFixed(2):'—'}</td><td>${best?(best.q/1000).toFixed(3):'—'}</td><td>${best?money(best.cost):'—'}</td><td>${why}</td></tr>`;}).join('');
 const counts=data.mountains.map(m=>({m,n:result.selected.reduce((n,t)=>n+Number(t.sat===m.id)+Number(t.sun===m.id),0)})).filter(x=>x.n).sort((a,b)=>b.n-a.n);$('allocation').innerHTML='<div class="usage">'+counts.map(({m,n})=>`<span>${m.name} <b>${n} ski days</b> · ${m.passType}</span>`).join('')+'</div><p class="note">Every mountain is capped at two ski days for the season. Magic uses both days together on one weekend.</p>';
}
async function solve(){if(busy)return;if(s.start>s.end){$('status').textContent='Check your season dates.';return;}if(s.snowpackWeight+s.terrainWeight>100){$('status').textContent='Depth and terrain weights must total 100% or less; the remainder is weather.';return;}busy=true;$('solve').disabled=true;$('solve').textContent='Optimizing…';$('status').textContent='Building weekend itineraries and solving quality, then cost…';try{await new Promise(r=>setTimeout(r,30));model=buildModel(data,routing,s,active,glpk);result=await optimize(model,glpk);dirty=false;persist();render();}catch(e){$('status').textContent='Unable to solve: '+e.message;}finally{busy=false;$('solve').disabled=false;$('solve').textContent='Optimize season';}}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===b));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('hidden',x.id!==b.dataset.tab));if(b.dataset.tab==='routes'&&routeMap)routeMap.show();});
$('explain-week').onchange=renderExplanation;$('weather-week').onchange=renderWeather;$('solve').onclick=solve;$('all').onclick=()=>{active={};renderWeekends();markDirty();};$('save-override').onclick=()=>{const el=$('override-price');if(!el.checkValidity()||el.value===''){el.reportValidity();return;}s.overrides[$('override-week').value+'_'+$('override-town').value]=Number(el.value);renderOverrides();markDirty();};
$('export').onclick=()=>{if(!result||dirty){$('status').textContent='Optimize the latest inputs before exporting.';return;}const rows=[['weekend','status','saturday','sunday','hotel_town','ski_hours','hotel_nights','miles','drive_hours','lodging','fuel','parking','food','extras','total']];for(const w of weekends(s)){const t=result.selected.find(t=>t.w===w);if(!t){rows.push([w,'Inactive']);continue;}rows.push([w,t.mode,data.mountains.find(m=>m.id===t.sat)?.name||'',data.mountains.find(m=>m.id===t.sun)?.name||'',data.hotels.find(h=>h.id===t.hotel)?.name||'',(t.satHours+t.sunHours).toFixed(1),t.hotel?2:0,Math.round(t.distance),t.drive.toFixed(1),...['lodging','fuel','parking','food','other','cost'].map(k=>t[k].toFixed(2))]);}download('ski-season-2026-27.csv',rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv');};
$('download-model').onclick=async()=>{if(!result?.lp||dirty){$('status').textContent='Optimize the latest inputs before downloading the model.';return;}download('ski-season.lp',await glpk.write(result.lp));};$('download-inputs').onclick=()=>download('ski-inputs.json',JSON.stringify({data,routing,settings:s,active},null,2),'application/json');
try{[data,routing,glpk]=await Promise.all([fetch('data.json').then(r=>{if(!r.ok)throw Error('Weather data unavailable');return r.json()}),fetch('routing.json').then(r=>r.json()),GLPK()]);for(const m of data.mountains){let old=saved.mountains?.find(x=>x.id===m.id);if(old)for(const key of ['enabled','preference','crowd','limit','parking','open','close'])if(old[key]!==undefined)m[key]=old[key];}for(const h of data.hotels){let old=saved.hotels?.find(x=>x.id===h.id);if(old)h.nightly=old.nightly;}for(const m of data.mountains)m.limit=passCapacity(m);routeMap=createRouteMap(data,routing);syncSettings();renderWeekends();renderData();await solve();}catch(e){$('status').textContent='Planner could not load: '+e.message;$('solve').disabled=true;}
